// Generates supabase/seed/cma_governance_registry_seed.sql from the
// deterministic registry built by cma-registry-build.mjs. Re-running
// this script against an unchanged docs/MASTER_MEASURES_REGISTER.csv
// produces byte-identical SQL (determinism/repeatability requirement,
// brief §9) — every insert is `on conflict (id) do update`, so applying
// the generated file twice against the same database is also safe.
//
// This script only WRITES the seed SQL file. It never connects to any
// database and never runs against production — applying the generated
// file anywhere is a separate, explicit step, consistent with brief §11
// ("Not authorized: ... Apply new registry migrations to production
// Supabase. Modify production registry data.").

import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildRegistry, coverageReport } from './cma-registry-build.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT_PATH = path.resolve(__dirname, '../../supabase/seed/cma_governance_registry_seed.sql');

function sqlStr(v) {
  if (v === null || v === undefined) return 'null';
  return `'${String(v).replace(/'/g, "''")}'`;
}
function sqlJsonb(v) {
  if (v === null || v === undefined) return 'null';
  return `${sqlStr(typeof v === 'string' ? v : JSON.stringify(v))}::jsonb`;
}
function sqlTextArray(arr) {
  if (!arr || arr.length === 0) return 'null';
  return `array[${arr.map(sqlStr).join(', ')}]`;
}

function buildSql(registry) {
  const lines = [];
  lines.push('-- CMA-2 Governance Registry — deterministic seed.');
  lines.push('-- GENERATED by .tooling/scripts/cma-registry-seed-generate.mjs from');
  lines.push('-- docs/MASTER_MEASURES_REGISTER.csv. Do not hand-edit — re-run the');
  lines.push('-- generator instead; it is deterministic (same CSV -> same output).');
  lines.push('-- Every statement is an idempotent upsert; applying this file more');
  lines.push('-- than once against the same database is safe and a no-op the second time.');
  lines.push('-- NOT applied to any live database by this session.');
  lines.push('');

  lines.push('-- ===== cma_base_facts =====');
  for (const f of registry.baseFacts) {
    lines.push(`insert into call_center.cma_base_facts (id, entity, field_name, data_type, source_table, description) values (${sqlStr(f.id)}, ${sqlStr(f.entity)}, ${sqlStr(f.field_name)}, ${sqlStr(f.data_type)}, ${sqlStr(f.source_table)}, ${sqlStr(f.description)}) on conflict (id) do update set entity = excluded.entity, field_name = excluded.field_name, data_type = excluded.data_type, source_table = excluded.source_table, description = excluded.description;`);
  }
  lines.push('');

  lines.push('-- ===== cma_dimensions =====');
  for (const d of registry.dimensions) {
    lines.push(`insert into call_center.cma_dimensions (id, label, canonical_values, normalization_rule, mapping_source) values (${sqlStr(d.id)}, ${sqlStr(d.label)}, ${sqlJsonb(d.canonical_values)}, ${sqlStr(d.normalization_rule)}, ${sqlStr(d.mapping_source)}) on conflict (id) do update set label = excluded.label, canonical_values = excluded.canonical_values, normalization_rule = excluded.normalization_rule, mapping_source = excluded.mapping_source;`);
  }
  lines.push('');

  lines.push('-- ===== cma_canonical_measures (migration_reference_measure_id deferred to the end, below, since cma_measures rows do not exist yet at this point) =====');
  for (const cm of registry.canonicalMeasures) {
    lines.push(`insert into call_center.cma_canonical_measures (id, canonical_name, business_definition, measure_class, governed_algorithm_status, governed_formula_ref, migration_reference_measure_id) values (${sqlStr(cm.id)}, ${sqlStr(cm.canonical_name)}, ${sqlStr(cm.business_definition)}, ${sqlStr(cm.measure_class)}, ${sqlStr(cm.governed_algorithm_status)}, ${sqlStr(cm.governed_formula_ref)}, null) on conflict (id) do update set canonical_name = excluded.canonical_name, business_definition = excluded.business_definition, measure_class = excluded.measure_class, governed_algorithm_status = excluded.governed_algorithm_status, governed_formula_ref = excluded.governed_formula_ref;`);
  }
  lines.push('');

  lines.push('-- ===== cma_measures =====');
  for (const m of registry.measures) {
    lines.push(`insert into call_center.cma_measures (id, canonical_measure_id, formula_ref, eligible_population, numerator, denominator, zero_denominator_handling, aggregation_method, depends_on_measures, status) values (${sqlStr(m.id)}, ${sqlStr(m.canonical_measure_id)}, ${sqlStr(m.formula_ref)}, ${sqlStr(m.eligible_population)}, ${sqlStr(m.numerator)}, ${sqlStr(m.denominator)}, ${sqlStr(m.zero_denominator_handling)}, ${sqlStr(m.aggregation_method)}, ${sqlTextArray(m.depends_on_measures)}, ${sqlStr(m.status)}) on conflict (id) do update set canonical_measure_id = excluded.canonical_measure_id, formula_ref = excluded.formula_ref, eligible_population = excluded.eligible_population, numerator = excluded.numerator, denominator = excluded.denominator, zero_denominator_handling = excluded.zero_denominator_handling, aggregation_method = excluded.aggregation_method, depends_on_measures = excluded.depends_on_measures, status = excluded.status;`);
  }
  lines.push('');

  lines.push('-- ===== cma_canonical_measures.migration_reference_measure_id backfill (now that cma_measures rows exist) =====');
  for (const cm of registry.canonicalMeasures) {
    if (!cm.migration_reference_measure_id) continue;
    lines.push(`update call_center.cma_canonical_measures set migration_reference_measure_id = ${sqlStr(cm.migration_reference_measure_id)} where id = ${sqlStr(cm.id)};`);
  }
  lines.push('');

  lines.push('-- ===== cma_measure_dimensions =====');
  for (const md of registry.measureDimensions) {
    lines.push(`insert into call_center.cma_measure_dimensions (measure_id, dimension_id) values (${sqlStr(md.measure_id)}, ${sqlStr(md.dimension_id)}) on conflict (measure_id, dimension_id) do nothing;`);
  }
  lines.push('');

  lines.push('-- ===== cma_measure_base_facts =====');
  for (const mbf of registry.measureBaseFacts) {
    lines.push(`insert into call_center.cma_measure_base_facts (measure_id, base_fact_id, role) values (${sqlStr(mbf.measure_id)}, ${sqlStr(mbf.base_fact_id)}, ${sqlStr(mbf.role)}) on conflict (measure_id, base_fact_id, role) do nothing;`);
  }
  lines.push('');

  lines.push('-- ===== cma_chart_visualizations =====');
  for (const cv of registry.chartVisualizations) {
    lines.push(`insert into call_center.cma_chart_visualizations (id, chart_name, visualizes_canonical_measure_id, visualizes_base_fact_id, presentation_dimension_id) values (${sqlStr(cv.id)}, ${sqlStr(cv.chart_name)}, ${sqlStr(cv.visualizes_canonical_measure_id)}, ${sqlStr(cv.visualizes_base_fact_id)}, ${sqlStr(cv.presentation_dimension_id)}) on conflict (id) do update set chart_name = excluded.chart_name, visualizes_canonical_measure_id = excluded.visualizes_canonical_measure_id, visualizes_base_fact_id = excluded.visualizes_base_fact_id, presentation_dimension_id = excluded.presentation_dimension_id;`);
  }
  lines.push('');

  const report = coverageReport(registry);
  lines.push('-- ===== Coverage summary at generation time (informational only) =====');
  lines.push(`-- ${JSON.stringify(report)}`);
  lines.push('-- Flagged, not inserted (no fixed single visualization target resolvable):');
  lines.push(`-- ${JSON.stringify(registry.flaggedCharts)}`);
  lines.push('');

  return lines.join('\n') + '\n';
}

const registry = buildRegistry();
const sql = buildSql(registry);
writeFileSync(OUT_PATH, sql, 'utf8');
console.log(`Wrote ${OUT_PATH}`);
console.log(JSON.stringify(coverageReport(registry), null, 2));
